def transform(grid):
    g=[row[:] for row in grid]
    R,C=len(g),len(g[0])
    # Each symbol is an 8-cell 3 ring around a 2 center. It launches a
    # downward continuation: center-column stem, then a cross at the next
    # full horizontal 2 divider, followed by a 3-wide bar below it.
    centers=[]
    for r in range(1,R-1):
        for c in range(1,C-1):
            if g[r][c]==2 and all(g[y][x]==3 for y in range(r-1,r+2) for x in range(c-1,c+2) if (y,x)!=(r,c)):
                centers.append((r,c))
    for r,c in centers:
        sep=next((y for y in range(r+1,R) if all(v==2 for v in g[y])),None)
        if sep is None: continue
        for y in range(r+2,sep):
            if g[y][c]==0: g[y][c]=1
        for x in range(c-1,c+2):
            if 0<=x<C and g[sep][x]==2: g[sep][x]=1
        for y in range(sep+1,R):
            for x in range(c-1,c+2):
                if 0<=x<C and g[y][x]==0: g[y][x]=1
    return g
